files.content:
* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: #1a1a2e;
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  padding: 16px;
  color: #e0e0e0;
}

.card {
  background: #16213e;
  border-radius: 16px;
  padding: 32px 24px;
  width: 100%;
  max-width: 640px;
  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.4);
  text-align: center;
}

h1 {
  font-size: 1.75rem;
  font-weight: 700;
  margin-bottom: 8px;
  color: #f0f0f0;
}

.subtitle {
  font-size: 1rem;
  color: #a0a0b0;
  margin-bottom: 28px;
}

.swatches {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
  justify-content: center;
  margin-bottom: 28px;
}

.swatch {
  flex: 1 1 100px;
  min-width: 80px;
  max-width: 120px;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 8px;
}

.color-box {
  width: 100%;
  aspect-ratio: 1;
  border-radius: 12px;
  border: 2px solid rgba(255, 255, 255, 0.15);
  transition: border-color 0.2s;
}

.swatch.locked .color-box {
  border-color: #ffd166;
  box-shadow: 0 0 0 2px #ffd166;
}

.hex-code {
  font-family: 'SF Mono', 'Fira Code', monospace;
  font-size: 0.9rem;
  letter-spacing: 0.5px;
  color: #c0c0d0;
  text-transform: uppercase;
}

.lock-btn {
  background: transparent;
  border: 2px solid #3a3a5c;
  border-radius: 8px;
  color: #a0a0b0;
  cursor: pointer;
  font-size: 1rem;
  padding: 4px 10px;
  transition: background 0.2s, border-color 0.2s, color 0.2s;
  line-height: 1.4;
}

.lock-btn:hover {
  border-color: #ffd166;
  color: #ffd166;
}

.lock-btn:focus-visible {
  outline: 3px solid #4cc9f0;
  outline-offset: 2px;
}

.lock-btn:active {
  background: rgba(255, 209, 102, 0.15);
}

.lock-btn[aria-pressed="true"] {
  background: #ffd166;
  border-color: #ffd166;
  color: #1a1a2e;
  font-weight: 600;
}

.generate-btn {
  background: #4cc9f0;
  border: none;
  border-radius: 10px;
  color: #1a1a2e;
  cursor: pointer;
  font-family: inherit;
  font-size: 1.1rem;
  font-weight: 600;
  padding: 14px 32px;
  transition: background 0.2s, transform 0.1s;
  width: 100%;
  max-width: 320px;
}

.generate-btn:hover {
  background: #72d6f5;
}

.generate-btn:focus-visible {
  outline: 3px solid #ffd166;
  outline-offset: 3px;
}

.generate-btn:active {
  transform: scale(0.97);
  background: #3ab8dd;
}

@media (max-width: 480px) {
  .card {
    padding: 24px 16px;
  }
  .swatches {
    gap: 8px;
  }
  .swatch {
    flex: 1 1 60px;
    min-width: 56px;
  }
  .hex-code {
    font-size: 0.75rem;
  }
  .lock-btn {
    font-size: 0.85rem;
    padding: 3px 8px;
  }
}

const swatchesContainer = document.getElementById('swatches');
const generateBtn = document.getElementById('generate');

const NUM_SWATCHES = 5;

let palette = [];
let locks = new Array(NUM_SWATCHES).fill(false);

function hslToHex(h, s, l) {
  s /= 100;
  l /= 100;
  const a = s * Math.min(l, 1 - l);
  const f = (n) => {
    const k = (n + h / 30) % 12;
    const color = l - a * Math.max(Math.min(k - 3, 9 - k, 1), -1);
    return Math.round(255 * color).toString(16).padStart(2, '0');
  };
  return `#${f(0)}${f(8)}${f(4)}`;
}

function generatePalette() {
  const baseHue = Math.random() * 360;
  const scheme = Math.floor(Math.random() * 3);
  const hues = [];
  for (let i = 0; i < NUM_SWATCHES; i++) {
    let offset;
    if (scheme === 0) {
      offset = i * 30;
    } else if (scheme === 1) {
      offset = (i % 2 === 0) ? i * 72 : i * 72 + 180;
    } else {
      offset = i * 72;
    }
    hues.push((baseHue + offset) % 360);
  }
  const newPalette = hues.map((h, i) => {
    const s = 55 + Math.random() * 25;
    const l = 45 + Math.random() * 20;
    return hslToHex(h, s, l);
  });
  return newPalette;
}

function render() {
  swatchesContainer.innerHTML = '';
  palette.forEach((hex, i) => {
    const swatch = document.createElement('div');
    swatch.className = 'swatch' + (locks[i] ? ' locked' : '');
    swatch.setAttribute('role', 'listitem');

    const colorBox = document.createElement('div');
    colorBox.className = 'color-box';
    colorBox.style.backgroundColor = hex;
    colorBox.setAttribute('aria-label', `Color ${hex}`);

    const hexCode = document.createElement('span');
    hexCode.className = 'hex-code';
    hexCode.textContent = hex.toUpperCase();

    const lockBtn = document.createElement('button');
    lockBtn.className = 'lock-btn';
    lockBtn.type = 'button';
    lockBtn.setAttribute('aria-pressed', String(locks[i]));
    lockBtn.setAttribute('aria-label', `Lock color ${hex.toUpperCase()}`);
    lockBtn.textContent = locks[i] ? '🔒 Locked' : '🔓 Lock';
    lockBtn.addEventListener('click', () => {
      locks[i] = !locks[i];
      render();
    });

    swatch.appendChild(colorBox);
    swatch.appendChild(hexCode);
    swatch.appendChild(lockBtn);
    swatchesContainer.appendChild(swatch);
  });
}

function newPalette() {
  const fresh = generatePalette();
  palette = palette.map((oldHex, i) => (locks[i] ? oldHex : fresh[i]));
  render();
}

palette = generatePalette();
render();

generateBtn.addEventListener('click', newPalette);
